            "لكل حقل مخصص نوع قيمة واحد بالضبط، يُختار وقت تعريف الحقل. ونوع القيمة هو ما يحدد عنصر التحكم الذي يظهر في النموذج، وما يقبله المنتج، وكيف تُخزَّن القيمة وكيف تُعرض بعد ذلك. تغطي هذه الصفحة الأنواع التسعة عشر كلها، واحدًا واحدًا، مع أمثلة إدخال مقبولة وأمثلة إدخال مرفوضة. وسبعة عشر منها تخزّن ما تكتبه أنت؛ أما النوعان الأخيران فيخزّنان إشارة إلى سجل في مكان آخر، ولهما صفحتان خاصتان بهما.",
          permanentTitle: "لا يمكن تغيير نوع القيمة أبدًا",
          permanentContent:
            "بمجرد حفظ الحقل يثبت نوع قيمته مدى حياة الحقل. ولا يوجد أي تحويل — فالإجابات المسجَّلة تحت النوع القديم ستفقد معناها. وإذا اخترت النوع الخطأ فلا بد من حذف الحقل وإعادة إنشائه، وتُفقد معه الإجابات المخزّنة عليه. اقضِ الدقيقة الإضافية في البداية.",

          orderTitle: "كيف تُفحَص القيمة المُرسَلة",
          orderIntro:
            "كل عملية حفظ تنفّذ الخطوات الأربع نفسها بالترتيب نفسه لكل نوع. ومعرفة هذا الترتيب تفسّر معظم المفاجآت.",
          order1:
            "هل القيمة فارغة؟ القيمة الغائبة، أو النص الفارغ، أو النص المكوّن من مسافات فقط، كلها تُعَد فارغة. وفي الاختيار المتعدد تُعَد القائمة الفارغة فارغة كذلك، أما في التاريخ والوقت وفي العملة وفي النوعين المرجعيين فلا تُعَد القيمة فارغة إلا إذا غاب جزآها معًا.",
          order2:
            "إذا كانت فارغة والحقل إلزامي، يُرفض الحفظ بالخطأ VALIDATION_REQUIRED. وإذا كانت فارغة والحقل غير إلزامي، تُمحى القيمة المخزّنة ولا يُنفَّذ شيء آخر — لا فحص نوع ولا أداة تحقق.",
          order3:
            "إذا لم تكن فارغة، تُنفَّذ قواعد النوع نفسه: حدود الطول، وتحليل الأرقام، وفحوص النطاق، ومطابقة الخيارات المسموح بها، وفحوص التنسيق.",
          order4:
            "أما حقل النص الذي أُرفقت به أداة تحقق، وفي هذه الحالة وحدها، فتُنفَّذ أداة التحقق في الأخير — بعد الحد العام البالغ 4,000 حرف وبعد حد الطول الأقصر الخاص بأداة التحقق نفسها.",
          orderKeyNote:
            "تفصيلة تستحق أن تعرفها قبل أن تقرأ أي رسالة خطأ: الرسالة تذكر مفتاح الحقل لا تسميته. فالحقل المسمى Nationality وله المفتاح nationality ينتج \"'nationality' expects a date.\" لا \"'Nationality'\".",

          thExample: "مثال إدخال",
          thOutcome: "ماذا يحدث",

          groupTextTitle: "النصوص والخيارات",
          textTitle: "نص [Text]",
          textStores:
            "سطر واحد من نص حر، حتى 4,000 حرف. ويظهر كحقل إدخال عادي من سطر واحد.",
          textChecks:
            "الفحص الوحيد هو حد الطول — إلا إذا أُرفقت أداة تحقق، وهو ما يجعل النص النوع الوحيد القادر على حمل فحص تنسيق. وتُخزَّن القيمة كما أُرسِلت بالضبط؛ فبخلاف الاختيار، النص لا يقتطع المسافات المحيطة.",
