          urlChecks:
            "يجب أن تكون القيمة عنوانًا مطلقًا مخططه http أو https بالضبط. وكل مخطط آخر مرفوض. ويُفحَص المخطط مرة أخرى عند الخروج، قبل أن تُعرض القيمة كرابط.",
          urlOk: "مقبولة، وتُعرض كرابط يفتح في تبويب جديد.",
          urlHttpOk:
            "مقبولة. فـ http المجرد مسموح به بشكل مقصود — فموقع شركة أو عنوان داخلي أثناء الإعداد بيانات مشروعة.",
          urlNoScheme:
            "مرفوضة: VALIDATION_INVALID_FORMAT. فالمضيف المجرد يُرفض بدلًا من تخمينه، حتى لا يضطر أي شيء إلى تحديد ما إذا كنت تقصد http أم https.",
          urlScheme:
            "مرفوضة: VALIDATION_INVALID_FORMAT. وهذا حدّ أمني حقيقي لا قاعدة أسلوب — ولأن المخطط يُفحَص مرة أخرى قبل العرض، فحتى القيمة المخزّنة قبل وجود هذا الفحص تظهر كنص خامل لا كرابط فعّال.",
          urlFtp: "مرفوضة: VALIDATION_INVALID_FORMAT. فـ http وhttps وحدهما على القائمة.",

          phoneTitle: "هاتف [Phone]",
          phoneStores:
            "رقم هاتف بالصيغة الدولية. ويظهر عبر منتقي دول بالأعلام والبحث، ويُعرض بعد ذلك مُعاد التنسيق لسهولة القراءة — مثل ‎+20 123 456 7890.",
          phoneChecks:
            "يجب أن تبدأ القيمة المخزّنة بعلامة +، وأن لا يكون رقمها الأول صفرًا، وأن تحمل ما بين 8 و15 رقمًا في المجموع. وهذا فحص على الشكل فقط.",
          phoneOk: "مقبولة، وتُعرض مُعادة التنسيق لا كالنص المخزّن المجرد.",
          phoneNoPlus: "مرفوضة: VALIDATION_INVALID_FORMAT. فعلامة + في البداية جزء من الصيغة.",
          phoneLeadingZero: "مرفوضة: VALIDATION_INVALID_FORMAT. فرمز الدولة لا يبدأ بصفر أبدًا.",
