          phoneUnassignable:
            "مقبولة من الخادم، الذي يفحص الشكل فقط ولا يفحص ما إذا كان الرقم يمكن أن يوجد فعلًا. أما منتقي النموذج نفسه فيفحص الرقم إضافيًا على خطة الترقيم الحقيقية للدولة المختارة، فلا يمكنك تكوين هذه القيمة من خلال الواجهة — بل بطلب يتجاوز النموذج فقط.",

          groupOtherTitle: "نعم/لا واللون",
          booleanTitle: "قيمة منطقية [Boolean]",
