          boolOne:
            "مرفوضة: VALIDATION_INVALID_FORMAT — ونص الرسالة \"expects a boolean\". فالرقم 1 لا يُقرأ باعتباره true.",
          boolYes: "مرفوضة: VALIDATION_INVALID_FORMAT. فلا yes/no ولا on/off مقبولة.",

          colorTitle: "لون [Color]",
          colorStores:
            "لون، يُخزَّن كقيمة سداسية. ويظهر كشبكة من عشرين عيّنة مع إدخال سداسي مخصص، ويُعرض بعد ذلك كالنص السداسي مع رقعة لون صغيرة مطابقة بجانبه.",
          colorChecks:
            "يجب أن تكون القيمة علامة # يتبعها ثلاث خانات سداسية بالضبط أو ست خانات بالضبط. وتُوحَّد حالة الأحرف إلى الصغيرة عند الحفظ؛ أما الطول فلا.",
