          colorShort:
            "مقبولة، وتُحفَظ كـ #abc. فالصيغة المختصرة لا تُوسَّع أبدًا إلى #aabbcc، وإن كان العارض يعتبرهما اللون نفسه — فيمكن للون الواحد أن يُخزَّن بطريقتين على سجلات مختلفة بشكل مشروع.",
          colorNoHash: "مرفوضة: VALIDATION_INVALID_FORMAT. فعلامة # في البداية مطلوبة.",
          colorBadLength: "مرفوضة: VALIDATION_INVALID_FORMAT. ثلاث خانات أو ست، ولا شيء بينهما.",
          colorNamed: "مرفوضة: VALIDATION_INVALID_FORMAT. فأسماء الألوان غير مقبولة، القيم السداسية فقط.",

          groupReferenceTitle: "الإشارة إلى سجل آخر",
          referenceGroupIntro:
            "النوعان الأخيران لا يخزّنان نصًا خاصًا بهما. فكل منهما يخزّن إشارة إلى سجل في مكان آخر من المنتج، والاسم الذي تراه يُجلَب من جديد في كل مرة يُعرَض فيها الحقل، ولا يُحفَظ إلى جانب الإشارة. وكلاهما يخزّن الجزأين نفسيهما — نوع السجل وهوية ذلك السجل — وكلاهما لا يَعُدّ القيمة فارغة إلا إذا غاب الجزآن معًا. وما يستحق أن يُقال عنهما أكثر بكثير مما يتّسع له جدول؛ وصفحتا الحقول المرجعية وعمليات البحث المرجعية تقولانه.",
          entityReferenceTitle: "مرجع كيان [EntityReference]",
          entityReferenceStores:
            "إشارة إلى سجل من أي نوع تستطيع بيئة النشر هذه الإجابة عنه ويُسمح لك بعرضه. ويظهر كمنتقٍ قابل للبحث في ذلك النوع من السجلات — يتقدّمه منتقٍ ثانٍ للنوع نفسه عندما لا يثبّت التعريف نوعًا واحدًا.",
          entityReferenceChecks:
            "الجزآن مطلوبان معًا. ويجب أن يكون نوع السجل مسجَّلًا، وأن يكون هو النوع المثبَّت إذا كان التعريف يثبّت واحدًا. ويجب أن تكون الهوية قابلة للقراءة. ويجب أيضًا أن تكون قادرًا على قراءة ذلك السجل في لحظة الحفظ، وهذا ما يمنع استخدام الإشارة للوصول إلى بيانات لا تستطيع فتحها مباشرة. ولكل فحص من هذه رسالة رفض خاصة به لا رسالة عامة.",
          refOk:
            "مقبولة. فتسجّل القيمة نوع السجل وهوية ذلك السجل معًا، ويعرض المنتقي اسم السجل الحالي من تلك اللحظة.",
          refIncomplete:
            "مرفوضة كمرجع ناقص. فنصف الإشارة لا يُعَد حقلًا فارغًا — بل يعني أن أحدًا بدأ الإجابة وتوقّف.",
          refIncompleteToo:
            "مرفوضة بالطريقة نفسها. فالهوية بلا نوع سجل تسمّي صفًّا بلا جدول، ولا يوجد ما يُبحَث فيه عنها.",
          refMismatch:
            "مرفوضة، والرسالة تسمّي ما يتوقعه الحقل وما وصل إليه معًا. فالتثبيت تقييد مقصود، وهذا الرفض هو عمله لا فشله.",
          refUnknownType:
            "مرفوضة: ENTITY_UNKNOWN_TYPE، مع ذكر المعرّف. ولا تُبلَغ إلا من طلب يتجاوز المنتقي، فالمنتقي لا يعرض نوع سجل غير مسجَّل أبدًا.",
          refInvalidId:
            "مرفوضة: ENTITY_INVALID_ID. فالهوية غير قابلة للقراءة ويجب أن تُعاد كما وصلت بالحرف — وحرف واحد متغيّر يجعلها غير قابلة للفهم.",
          refForbidden:
            "مرفوضة: AUTH_FORBIDDEN، مع ذكر الحقل. فتخزين إشارة إلى سجل هو قراءة مؤجَّلة لذلك السجل، فيحتاج إلى الصلاحية نفسها التي تحتاجها قراءته.",
          refEmpty:
            "تُعَد فارغة: تُمحى إن كان الحقل غير إلزامي، وتُرفض بالخطأ VALIDATION_REQUIRED إن كان إلزاميًا. وغياب الجزأين معًا هو وحده ما يُعَد فراغًا.",
          exRefOk: "عضو طاقم مختار من المنتقي",
          exRefTypeOnly: "نوع سجل مختار، بدون اختيار سجل",
          exRefIdOnly: "سجل مختار، بدون إرسال نوع السجل",
          exRefWrongType: "شخص، على حقل مثبَّت على أعضاء الطاقم",
          exRefUnknownType: "نوع سجل غير مسجَّل",
          exRefEdited: "هوية مخزّنة تغيّر فيها حرف واحد",
          exRefNoAccess: "سجل من نوع لا يُسمح لك بعرضه",
          exRefBothBlank: "ترك الجزأين فارغين",

          userReferenceTitle: "مرجع مستخدم [UserReference]",
          userReferenceStores:
            "إشارة إلى حساب مستخدم — المسؤول عن التنفيذ، أو من راجَع، أو مدير الحساب. ويظهر كمنتقٍ قابل للبحث في حسابات المستخدمين، ولا يعرض أبدًا عنصرًا لاختيار نوع السجل، لأن النوع واحد لا غير.",
          userReferenceChecks:
            "كل فحص يجريه مرجع الكيان، وفوقه قاعدة أضيق: النوع الوحيد المقبول هو حساب المستخدم. وهذه القائمة مثبَّتة في المنصة لا في الإعدادات، ومحاولة توجيه هذا النوع إلى أي شيء آخر مرفوضة عند تعريف الحقل وعند حفظ القيمة على السواء.",
          usrOk: "مقبولة، تمامًا كما في مرجع الكيان. فالقيمة تصف نفسها بالطريقة نفسها.",
          usrDormant:
            "مقبولة. فالحساب المقفل خامد لا محذوف: هو موجود، ويعرضه المنتقي مع علامة \"غير نشط\"، وهو إجابة مشروعة عن أمر وقع بالفعل.",
          usrAdminRefused:
            "مرفوضة، برسالة تسمّي ما هو مسموح. فالمسؤول قد لا ينتمي إلى أي مساحة عمل على الإطلاق، وهذه هي الخصيصة الوحيدة التي يجب ألّا تتوفّر في هدف مرجعي.",
          usrGroupRefused:
            "مرفوضة بالطريقة نفسها. فالمجموعة آمنة القراءة لكنها ليست شخصًا، وحقل نوعه مرجع مستخدم يحلّ إلى مجموعة يكون كاذبًا فيما يحمله.",
          usrThemeRefused:
            "مرفوضة بالطريقة نفسها. فصفّ فهرس مشترك على مستوى المنصة لا ينتمي إلى أي مساحة عمل، وليس شخصًا كذلك — مستثنى لسببين لا سبب واحد.",
          usrEmpty: "تُعَد فارغة بالشروط نفسها تمامًا كما في مرجع الكيان.",
          exUsrOk: "حساب مستخدم مختار من المنتقي",
