          featSearch: "قابل للبحث ومقسَّم إلى صفحات، ويصرّح بما لا يستطيع",
          featSearchDesc:
            "يبحث المنتقي في سجلات الوحدة الهدف صفحةً صفحةً، ويضع علامة على السجل الخامد بدلًا من إخفائه، ويقول بالكلمات إنه لا يوجد ما يُسمح لك بالإشارة إليه — لا قائمة منسدلة فارغة تُقرأ على أنها \"لا توجد سجلات\".",
