          aspConfig: "ما تُعِدّه أنت",
          entConfig:
            "اختياريًا، نوع الكيان الهدف على التعريف. وترك الحقل غير مثبَّت خيار حقيقي ومدعوم على الدوام، لا حالة ناقصة.",
          usrConfig:
            "لا شيء على الإطلاق. فلا يوجد منتقي هدف على نموذج التعريف لهذا النوع، لأنه لا يوجد قرار يُتخذ.",
          aspPicker: "ما يراه من يملأ الحقل",
