          usrPicker: "قائمة واحدة قابلة للبحث في حسابات المستخدمين. ولا يوجد عنصر لاختيار النوع أبدًا.",
          aspUse: "استخدمه عندما",
          entUse:
            "تكون الإجابة سجلًا تشغيليًا — عضو طاقم، أو شخصًا، أو منشأة — أو عندما تشير سجلات مختلفة تحت الحقل نفسه إلى أنواع مختلفة بشكل مشروع.",
          usrUse:
            "تكون الإجابة حسابًا: المسؤول عن التنفيذ، أو من راجَع، أو مدير الحساب، أو من اعتمد.",
