          globalTenantView:
            "داخل مساحة العمل تعرض المجموعة العامة شارة عام ولا تعرض أي عنصر تعديل أو حذف أو تحريك على الإطلاق. وهذه ليست الواجهة تخفي شيئًا اعتباطًا — فالخادم سيرفض تلك العمليات، فلا تُعرَض عناصرها.",

