          uaeTitle: "الإمارات العربية المتحدة غائبة بشكل مقصود",
          uaeContent:
            "الإمارات ليس لديها نظام رمز بريدي وطني، فلا يوجد تنسيق حقيقي تُفحَص القيمة عليه — لا صارم ولا متساهل. وهي ليست مدخلًا ناقصًا في انتظار الإضافة: فمحاولة استخدامها تُرفض وقت التعريف برسالة توضيحية خاصة بها، مختلفة عن رسالة الدولة غير المدعومة العامة التي كنت ستحصل عليها لخطأ إملائي، وتخبرك أن تترك الحقل بدون أداة تحقق بدلًا من ذلك. والقائمة المنسدلة لا تعرضها أبدًا.",

