          thCode: "الرمز",
          thWhenItFires: "متى يظهر",
          codeInvalidFormat:
            "معظم حالات فشل أدوات التحقق: شكل لا يطابق، أو رقم تحقق لا يصح، أو قيمة ليست على قائمة أحد قيم قائمة محددة، أو علامة \"يحتوي على\" أو \"يبدأ بـ\" غائبة، أو رمز بريدي لا يطابق دولته.",
          codeRange: "النطاق الرقمي — القيمة خارج الحدود، أو ليست رقمًا على الإطلاق.",
