          limit6:
            "لا يمكن كتابتها باليد. فلا يوجد أي إدخال لتعبير نمطي أو نمط في أي موضع، وذلك بحسب التصميم، والفحوص المدمجة الثلاثة عشر هي المجموعة الكاملة.",
